// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        uint256 v = bound(amount, 1, 1e30);
        // fund the contract via its payable fallback with v + 1 wei
        vm.deal(address(this), v + 1);
        (bool funded, ) = address(c).call{value: v + 1}("");
        assertTrue(funded);
        assertTrue(address(c).balance == v + 1);

        // owner (this test contract) requests withdrawal of exactly v
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector, v));
        assertTrue(ok);

        // RULE: withdraw(v) removes exactly v wei, leaving the extra 1 wei
        assertTrue(address(c).balance == 1);
    }
}
